def verify(kind):
 def git(*args):return subprocess.check_output(['git',*args],cwd=sources[kind],text=True,timeout=10).strip()
 sha=protocol['base_commit' if kind=='base' else 'implementation_commit'];assert git('rev-parse','HEAD')==sha and not git('status','--porcelain')
 return {'source_revision':sha,'tree':git('rev-parse','HEAD^{tree}'),'tracked_tree_clean':True}
