 v=subprocess.run(['docker','inspect',name,'--format','{{index .Config.Labels "codex.qec.paired"}}'],capture_output=True,text=True,timeout=10)
 if v.returncode==0:
  assert v.stdout.strip()==nonce
  subprocess.run(['docker','rm','-f',name],capture_output=True,timeout=10,check=True)
def stop(sig,frame):
 if active:cleanup(active)
 raise SystemExit(128+sig)
signal.signal(signal.SIGTERM,stop);signal.signal(signal.SIGINT,stop)
records=[];started=time.monotonic()
for batch in [128,4096]:
 for index,kind in enumerate(protocol['order_per_batch']):
