  args=['docker','run','--rm','--pull=never','--name',name,'--label','codex.qec.paired='+nonce,'--network=none','--read-only','--tmpfs','/tmp:rw,size=256m','--memory=4g','--cpus=2','--pids-limit=128','-v',str(sources[kind])+':/task/source:ro','-v','/tmp/fq-qec-shot-scaling-20261025-'+host+'/deps:/task/deps:ro','-v',str(p/'observer.py')+':/task/observer.py:ro','-w','/tmp']
  for key,value in {'HOME':'/tmp','PYTHONPATH':'/task/source:/task/deps','PYTHONDONTWRITEBYTECODE':'1','OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1','OPENBLAS_NUM_THREADS':'1','MPLCONFIGDIR':'/tmp/mpl','FQ_SOURCE_REVISION':before['source_revision'],'FQ_SOURCE_TREE':before['tree']}.items():args+=['-e',key+'='+value]
