   rows=[json.loads(line) for line in (p/(label+'.jsonl')).read_text().splitlines()]
   assert len(rows)==6 and rows[-1]['kind']=='diagnostics' and rows[-1]['completed_shots']==65537
  records.append(r);(p/'controller-results.json').write_text(json.dumps({'records':records,'elapsed_wall_seconds':time.monotonic()-started},indent=2));print(json.dumps(r),flush=True)
result={'records':records,'elapsed_wall_seconds':time.monotonic()-started,'complete':len(records)==12 and all(r['status']=='complete' for r in records)}
